app().registerHandler("/users/{id}",
    [](const HttpRequestPtr &req, std::function<void(const HttpResponsePtr &)> &&cb) {
        auto id = std::stol(req->getParameter("id"));
        auto user = domain::find_user(id);                  // domain
        if (!user) { cb(HttpResponse::newNotFoundResponse()); return; }
        Json::Value body; body["id"] = user->id; body["name"] = user->name;
        cb(HttpResponse::newHttpJsonResponse(body));        // responder
    });
